use xiom.io;

enum DivResult {
  Ok(n: Int),
  DivByZero,
}

fn safe_divide(a: Int, b: Int) -> DivResult {
  if b == 0 {
    return DivResult.DivByZero;
  }
  return DivResult.Ok(a / b);
}

fn chain_divide(a: Int, b: Int, c: Int) -> DivResult {
  let r1 = safe_divide(a, b);
  match r1 {
    Ok(n) => { return safe_divide(n, c); }
    DivByZero => { return DivResult.DivByZero; }
  }
}

fn main() -> Int {
  let result = chain_divide(100, 5, 2);
  match result {
    Ok(n) => { return n; }
    DivByZero => { return -1; }
  }
}
